<?php defined('BASEPATH') or exit('No direct script access allowed');
class Enterprise_360_webhook extends App_Controller {
 public function twiml(){ $to=trim((string)$this->input->get('to',true)); header('Content-Type: text/xml'); echo '<?xml version="1.0" encoding="UTF-8"?><Response><Dial'.(get_option('enterprise_twilio_record_calls')==='1'?' record="record-from-answer-dual"':'').'><Number>'.htmlspecialchars($to,ENT_XML1,'UTF-8').'</Number></Dial></Response>'; }
 public function status(){ $sid=(string)$this->input->post('CallSid',true);$status=(string)$this->input->post('CallStatus',true);$duration=(int)$this->input->post('CallDuration');$recording=(string)$this->input->post('RecordingUrl',true);$t=db_prefix().'sce_call_logs';if($sid!==''&&$this->db->table_exists($t)){$row=$this->db->where('call_sid',$sid)->get($t)->row_array();$data=['status'=>$status,'duration_seconds'=>$duration,'ended_at'=>$status==='completed'?date('Y-m-d H:i:s'):null,'recording_url'=>$recording?:null,'has_recording'=>$recording!==''?1:0];if($row)$this->db->where('id',$row['id'])->update($t,$data);else{$data=array_merge($data,['call_sid'=>$sid,'direction'=>'unknown','from_number'=>(string)$this->input->post('From',true),'to_number'=>(string)$this->input->post('To',true),'created_at'=>date('Y-m-d H:i:s')]);$this->db->insert($t,$data);}} http_response_code(204); }
}
